<template>
  <div class="research-page">
    <section class="hero">
      <div><p>VERIFIABLE RESEARCH RUNTIME</p><h1>从研究问题到可审计证据链</h1><span>先计划，再执行；每一步都显示来源、置信度、限制与人工复核门。</span></div>
      <div class="hero-badge"><b>计划 · 执行 · 验证</b><small>材料隔离 · 有界调度 · 受控学习</small></div>
    </section>
    <div v-if="error" class="alert" role="alert"><span>{{ error }}</span><button @click="error=''">×</button></div>

    <div class="layout">
      <section class="panel composer">
        <header><div><p>RESEARCH BRIEF</p><h2>定义科研任务</h2></div><span>{{ objective.length }}/4000</span></header>
        <textarea v-model="objective" maxlength="4000" placeholder="例如：系统评价某干预对目标人群主要结局的影响，并提出可复现的验证实验与论文框架。"></textarea>
        <label class="field-label">能力范围</label>
        <div class="domains">
          <label v-for="item in domains" :key="item.value" :class="{selected:selectedDomains.includes(item.value)}">
            <input v-model="selectedDomains" type="checkbox" :value="item.value"><span>{{ item.icon }}</span><b>{{ item.label }}</b><small>{{ item.hint }}</small>
          </label>
        </div>
        <div class="upload-box">
          <div><b>研究材料</b><small>CSV / TSV / TXT / MD / JSON / PDF / 图像，单文件 ≤ 25 MiB</small></div>
          <label class="upload"><input type="file" multiple accept=".csv,.tsv,.txt,.md,.json,.pdf,.png,.jpg,.jpeg,.tif,.tiff" @change="uploadFiles">{{ uploading?'正在预检…':'＋ 添加材料' }}</label>
          <div v-if="selectedArtifacts.length" class="files">
            <button v-for="item in selectedArtifacts" :key="item.id" @click="removeArtifact(item.id)"><span>{{ modalityIcon(item.summary?.modality) }}</span><div><b>{{ item.name }}</b><small>{{ sizeLabel(item.size_bytes) }} · {{ item.summary?.modality||'文件' }}</small></div><i>×</i></button>
          </div>
        </div>
        <div class="options">
          <label><input v-model="networkAllowed" type="checkbox"><b>允许只读网络检索</b><small>关闭后，PubMed 步骤会被策略明确阻止</small></label>
          <label>并发上限 <select v-model.number="maxConcurrency"><option v-for="n in 4" :key="n" :value="n">{{ n }}</option></select></label>
        </div>
        <div class="actions"><button :disabled="!canSubmit||planning" @click="previewPlan">{{ planning?'规划中…':'预览计划' }}</button><button class="primary" :disabled="!canSubmit||starting" @click="startRun">{{ starting?'创建中…':'开始科研任务' }} →</button></div>
        <div v-if="planPreview" class="plan">
          <header><div><p>EXECUTION PLAN</p><h3>{{ planPreview.steps.length }} 个可审计步骤</h3></div><b>{{ planPreview.budget.cost_units }} units</b></header>
          <ol><li v-for="(step,index) in planPreview.steps" :key="step.key"><span>{{ index+1 }}</span><div><b>{{ step.title }}</b><small>{{ step.dependencies.length?`依赖 ${step.dependencies.join('、')}`:'可立即执行' }}</small></div></li></ol>
          <p>人工复核门：{{ planPreview.review_gates.join('、')||'无' }}；计划外能力默认拒绝。</p>
        </div>
      </section>

      <aside class="panel history">
        <header><div><p>RUN HISTORY</p><h2>最近任务</h2></div><button @click="loadRuns">刷新</button></header>
        <div class="runs" v-if="runs.length"><button v-for="run in runs" :key="run.id" :class="{active:activeRun?.id===run.id}" @click="selectRun(run.id)"><i :class="run.status"></i><div><b>{{ run.objective }}</b><small>{{ statusLabel(run.status) }} · {{ timeLabel(run.created_at) }}</small></div><span>{{ run.progress }}%</span></button></div>
        <div v-else class="empty"><b>还没有科研任务</b><small>计划与证据链会保存在当前账户。</small></div>
        <div class="learning"><div><small>受控学习</small><b>{{ proposals.length }} 个待审核提案</b></div><button v-if="proposals.length" @click="showLearning=!showLearning">{{ showLearning?'收起':'审核' }}</button>
          <article v-for="item in (showLearning?proposals:[])" :key="item.id"><b>{{ item.title }}</b><p>{{ item.proposed_change?.instruction }}</p><div><button @click="decide(item.id,'rejected')">拒绝</button><button @click="decide(item.id,'applied')">应用</button></div></article>
        </div>
      </aside>
    </div>

    <section v-if="activeRun" class="panel detail">
      <header class="run-head"><div><p>RESEARCH RUN · {{ activeRun.id.slice(0,8) }}</p><h2>{{ activeRun.objective }}</h2><span>{{ activeRun.domains.map(domainLabel).join(' · ') }}</span></div><div><b :class="activeRun.status">{{ statusLabel(activeRun.status) }}</b><strong>{{ activeRun.progress }}%</strong><button v-if="activeRun.status==='completed'" @click="downloadReport" title="聚合目标、证据、统计与缺口为可下载 PDF">生成简报 PDF</button><button v-if="['pending','running'].includes(activeRun.status)" @click="cancelRun">取消</button></div></header>
      <div class="progress"><i :style="{width:`${activeRun.progress}%`}"></i></div>
      <div v-if="activeRun.result?.has_gaps" class="gap"><b>结果包含证据缺口</b><span>请检查警告与人工复核门，不要把降级输出当作已证实结论。</span></div>
      <div class="timeline">
        <article v-for="step in activeRun.steps" :key="step.key" class="step" :class="step.status">
          <div class="marker"><span>{{ step.order+1 }}</span><i></i></div>
          <div class="step-main"><header><div><p>{{ step.capability }}</p><h3>{{ step.title }}</h3></div><div><b>{{ stepStatus(step.status) }}</b><span v-if="step.confidence">置信度 {{ Math.round(step.confidence*100) }}%</span><small v-if="step.duration_ms">{{ step.duration_ms }} ms</small></div></header>
            <div v-if="step.warnings?.length" class="warnings"><p v-for="item in step.warnings" :key="item">△ {{ item }}</p></div>
            <div v-if="step.key==='literature'&&step.output?.evidence_table" class="output evidence"><div class="output-title"><b>证据表</b><span>{{ step.output.evidence_table.length }} 条</span></div><a v-for="item in step.output.evidence_table.slice(0,8)" :key="item.id" :href="item.locator" target="_blank" rel="noreferrer"><span>{{ item.year||'—' }}</span><div><b>{{ item.title }}</b><small>{{ item.authors?.slice(0,3).join('、')||'作者缺失' }} · {{ item.id }}</small></div><i>↗</i></a><p class="limit">{{ step.output.evidence_gap }}</p></div>
            <div v-else-if="step.key==='experiment'&&step.output?.estimand" class="output"><div class="output-title"><b>实验设计契约</b><span>{{ step.output.study_type }}</span></div><dl><template v-for="(value,key) in step.output.estimand" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></template></dl><div class="columns"><section><b>偏倚控制</b><p v-for="x in step.output.bias_controls" :key="x">✓ {{ x }}</p></section><section><b>质量门</b><p v-for="x in step.output.quality_gates" :key="x">✓ {{ x }}</p></section><section><b>伦理门</b><p v-for="x in step.output.ethics_gate" :key="x">! {{ x }}</p></section></div></div>
            <div v-else-if="step.key==='data'&&step.output?.profiles" class="output"><div class="output-title"><b>数据质量报告</b><span>{{ step.output.profiles.length }} 个表格</span></div><section v-for="profile in step.output.profiles" :key="profile.artifact_id" class="profile"><h4>{{ profile.name }} · {{ profile.rows_scanned }} 行 × {{ profile.column_count }} 列</h4><div><span v-for="col in profile.columns.slice(0,12)" :key="col.name"><b>{{ col.name }}</b><small>{{ col.inferred_type }} · 缺失 {{ Math.round(col.missing_rate*100) }}%</small></span></div></section><p v-for="item in step.output.generated_artifacts||[]" :key="item.id">▧ {{ item.name }} · {{ sizeLabel(item.size_bytes) }}</p></div>
            <div v-else-if="step.key==='writing'&&step.output?.sections" class="output"><div class="output-title"><b>写作脚手架</b><span>{{ step.output.draft_status }}</span></div><div class="section-grid"><section v-for="s in step.output.sections" :key="s.name"><b>{{ s.name }}</b><p v-for="x in s.requirements" :key="x">{{ x }}</p></section></div><p class="policy">{{ step.output.citation_policy }}</p></div>
            <div v-else-if="step.key==='integrity'&&step.output?.findings" class="output integrity"><div class="output-title"><b>规范检查</b><span>{{ step.output.findings.length }} 项</span></div><article v-for="f in step.output.findings" :key="f.check_id" :class="f.severity"><span>{{ f.severity }}</span><div><b>{{ f.message }}</b><p>{{ f.recommendation }}</p></div></article><p v-for="x in step.output.limitations" :key="x" class="limit">边界：{{ x }}</p></div>
            <div v-else-if="step.output&&Object.keys(step.output).length" class="output"><pre>{{ pretty(step.output) }}</pre></div>
          </div>
        </article>
      </div>
      <footer v-if="activeRun.status==='completed'" class="feedback"><div><p>HUMAN REVIEW</p><h3>这次结果是否符合科研要求？</h3><span>纠正只生成待审核提案，不会静默改变智能体。</span></div><div class="rating"><button v-for="n in 5" :key="n" :class="{active:feedback.rating===n}" @click="feedback.rating=n">{{ n }}</button></div><textarea v-model="feedback.correction" placeholder="可选：说明下次应保持或修正的稳定做法…"></textarea><label><input v-model="feedback.accepted" type="checkbox">我已人工检查关键结果</label><button class="submit" :disabled="feedbackSent" @click="submitFeedback">{{ feedbackSent?'已记录':'提交反馈' }}</button></footer>
    </section>
  </div>
</template>

<script setup>
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import axios from 'axios'
import {apiError} from '../state/session'
const objective=ref(''),selectedDomains=ref(['literature','discovery','experiment','data','writing','integrity']),selectedArtifactIds=ref([]),artifacts=ref([]),runs=ref([]),activeRun=ref(null),planPreview=ref(null),proposals=ref([])
const networkAllowed=ref(true),maxConcurrency=ref(2),planning=ref(false),starting=ref(false),uploading=ref(false),error=ref(''),showLearning=ref(false),feedbackSent=ref(false);const feedback=reactive({rating:5,accepted:false,correction:''});let pollTimer
const domains=[{value:'literature',label:'文献证据',icon:'⌕',hint:'检索、去重、证据表'},{value:'discovery',label:'假设演化',icon:'◇',hint:'生成、反思、排序、演化'},{value:'experiment',label:'实验设计',icon:'⌬',hint:'估计目标、偏倚与伦理'},{value:'data',label:'数据分析',icon:'▦',hint:'质控、统计契约与绘图'},{value:'writing',label:'科研写作',icon:'¶',hint:'主张—证据约束'},{value:'integrity',label:'学术规范',icon:'✓',hint:'引用、统计与伦理检查'}]
const selectedArtifacts=computed(()=>artifacts.value.filter(x=>selectedArtifactIds.value.includes(x.id))),canSubmit=computed(()=>objective.value.trim().length>=6&&selectedDomains.value.length)
const body=(execute=false)=>({objective:objective.value.trim(),domains:selectedDomains.value,artifact_ids:selectedArtifactIds.value,context:{},network_allowed:networkAllowed.value,max_concurrency:maxConcurrency.value,execute})
async function previewPlan(){planning.value=true;error.value='';try{planPreview.value=(await axios.post('/api/v1/research/plan',body())).data.plan}catch(e){error.value=apiError(e,'计划生成失败')}finally{planning.value=false}}
async function startRun(){starting.value=true;error.value='';feedbackSent.value=false;try{activeRun.value=(await axios.post('/api/v1/research/runs',body(true))).data;planPreview.value=activeRun.value.plan;await loadRuns();poll()}catch(e){error.value=apiError(e,'任务创建失败')}finally{starting.value=false}}
async function uploadFiles(event){const files=[...(event.target.files||[])];event.target.value='';uploading.value=true;try{for(const file of files){const form=new FormData();form.append('file',file);const item=(await axios.post('/api/v1/research/artifacts',form,{timeout:90000})).data;artifacts.value.unshift(item);selectedArtifactIds.value.push(item.id)}}catch(e){error.value=apiError(e,'材料预检失败')}finally{uploading.value=false}}
function removeArtifact(id){selectedArtifactIds.value=selectedArtifactIds.value.filter(x=>x!==id)}
async function loadArtifacts(){try{artifacts.value=(await axios.get('/api/v1/research/artifacts')).data.artifacts||[]}catch(_){}}
async function loadRuns(){try{runs.value=(await axios.get('/api/v1/research/runs')).data.runs||[]}catch(e){error.value=apiError(e,'任务列表加载失败')}}
async function selectRun(id){try{activeRun.value=(await axios.get(`/api/v1/research/runs/${id}`)).data;if(['pending','running'].includes(activeRun.value.status))poll()}catch(e){error.value=apiError(e,'任务详情加载失败')}}
function poll(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{if(!activeRun.value||!['pending','running'].includes(activeRun.value.status)){clearInterval(pollTimer);return}await selectRun(activeRun.value.id);await loadRuns()},1200)}
async function cancelRun(){try{await axios.post(`/api/v1/research/runs/${activeRun.value.id}/cancel`);await selectRun(activeRun.value.id)}catch(e){error.value=apiError(e,'取消失败')}}
async function downloadReport(){try{const res=await axios.post(`/api/v1/research/runs/${activeRun.value.id}/report`,{format:'pdf'},{responseType:'blob'});const url=URL.createObjectURL(new Blob([res.data],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download=`research-brief-${activeRun.value.id.slice(0,8)}.pdf`;a.click();URL.revokeObjectURL(url)}catch(e){error.value=apiError(e,'简报生成失败')}}
async function loadProposals(){try{proposals.value=(await axios.get('/api/v1/research/learning-proposals',{params:{status:'pending'}})).data.proposals||[]}catch(_){}}
async function submitFeedback(){try{await axios.post(`/api/v1/research/runs/${activeRun.value.id}/feedback`,{...feedback,propose_learning:true});feedbackSent.value=true;await loadProposals()}catch(e){error.value=apiError(e,'反馈失败')}}
async function decide(id,decision){try{await axios.post(`/api/v1/research/learning-proposals/${id}/decision`,{decision});await loadProposals()}catch(e){error.value=apiError(e,'提案处理失败')}}
const statusLabel=x=>({pending:'待执行',running:'执行中',completed:'已完成',failed:'失败',cancelled:'已取消',interrupted:'启动恢复：已中断'}[x]||x),stepStatus=x=>({pending:'等待',running:'执行中',completed:'完成',degraded:'降级完成',failed:'失败',blocked:'策略阻止',cancelled:'已取消',interrupted:'已中断'}[x]||x),domainLabel=x=>domains.find(d=>d.value===x)?.label||(x==='multimodal'?'多模态预检':x),modalityIcon=x=>({table:'▦',text:'¶',document:'▤',image:'▧',structured:'{}'}[x]||'◇'),sizeLabel=(b=0)=>b<1024?`${b} B`:b<1048576?`${(b/1024).toFixed(1)} KiB`:`${(b/1048576).toFixed(1)} MiB`,timeLabel=x=>x?new Date(x).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'',pretty=x=>JSON.stringify(x,null,2).slice(0,8000)
onMounted(async()=>{await Promise.all([loadArtifacts(),loadRuns(),loadProposals()]);if(runs.value[0])await selectRun(runs.value[0].id)});onBeforeUnmount(()=>clearInterval(pollTimer))
</script>

